create table xxventuri.test_products_t (
    id           number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    product_id   number,
    product_code varchar2(100 byte),
    location     varchar2(50 byte)
);

alter table xxventuri.test_products_t add primary key ( id )
    using index enable;


